	,(375, 'VIEW_ONLY_SITE_CLOSEOUT_TIME', 'VIEW_ONLY_SITE_CLOSEOUT_TIME', '8F7070F6-9A51-4C08-83C3-5E1FA7B35A16', N'7/3/2024 8:06:00 AM -04:00', 'Administrator', N'7/3/2024 8:06:00 AM -04:00', 'Administrator')

) AS Source ([RightIndex], [RightCode], [RightName], [RightGuid], [CreatedDate], [CreatedBy], [UpdatedDate], [UpdatedBy])
ON (Target.[RightIndex] = Source.[RightIndex])
WHEN MATCHED AND (Target.[RightCode] <> Source.[RightCode] 
					OR Target.[RightName] <> Source.[RightName]
					OR Target.[RightGuid] <> Source.[RightGuid]) THEN
	UPDATE SET [RightCode] = Source.[RightCode]
				, [RightName] = Source.[RightName]
				, [RightGuid] = Source.[RightGuid]
				, [CreatedDate] = Source.[CreatedDate]
				, [CreatedBy] =	Source.[CreatedBy]
				, [UpdatedDate] = Source.[UpdatedDate]
				, [UpdatedBy] =	Source.[UpdatedBy]
WHEN NOT MATCHED THEN
	INSERT ([RightIndex], [RightCode], [RightName], [RightGuid], [CreatedDate], [CreatedBy], [UpdatedDate], [UpdatedBy])
		VALUES (Source.[RightIndex],Source.[RightCode],Source.[RightName],Source.[RightGuid],Source.[CreatedDate],Source.[CreatedBy],Source.[UpdatedDate],Source.[UpdatedBy])
OUTPUT
   $action AS ActionType,
   deleted.[RightIndex],
   inserted.[RightIndex],
   deleted.[RightCode],
   inserted.[RightCode],
   deleted.[RightName],
   inserted.[RightName],
   deleted.[RightGuid],
   inserted.[RightGuid],
   deleted.[CreatedDate],
   inserted.[CreatedDate],
   deleted.[CreatedBy],
   inserted.[CreatedBy],
   deleted.[UpdatedDate],
   inserted.[UpdatedDate],
   deleted.[UpdatedBy],
   inserted.[UpdatedBy]
INTO @tblRightRefData;

SELECT @RightRefDataInserted = COUNT(*) FROM @tblRightRefData WHERE ActionType IN ( 'INSERT' );
SELECT @RightRefDataUpdated = COUNT(*) FROM @tblRightRefData WHERE ActionType IN ( 'UPDATE' )
SELECT @RightRefDataDeleted = COUNT(*) FROM @tblRightRefData WHERE ActionType IN ( 'DELETE' )

IF (@RightRefDataInserted > 0)
BEGIN
	PRINT '** ' + CONVERT(NVARCHAR(25), @RightRefDataInserted) + ' NEW RECORDS INSERTED INTO [lookup].[tblRight] **'
	PRINT ''
END

IF (@RightRefDataUpdated > 0)
BEGIN
	PRINT '** ' + CONVERT(NVARCHAR(25), @RightRefDataUpdated) + ' EXISTING RECORDS UPDATED IN [lookup].[tblRight] **'
	PRINT ''
	SELECT * FROM @tblRightRefData WHERE ActionType IN ( 'UPDATE' );
END

SET NOCOUNT OFF
